 3→
 4→type VariantMapping<P> = {
 5→  [K in (typeof Variant)[keyof typeof Variant]]: P;
 6→};
 7→
 8→const mapLeafyGreenVariantToToast: VariantMapping<ToastVariant> = {
 9→  [Variant.Important]: "warning",
10→  [Variant.Note]: "info",
11→  [Variant.Progress]: "progress",
12→  [Variant.Success]: "success",
13→  [Variant.Warning]: "error",
14→};
15→
16→const mapLeafyGreenVariantToTitle: VariantMapping<string> = {
17→  [Variant.Important]: "Warning!",
18→  [Variant.Note]: "Something Happened!",
19→  [Variant.Progress]: "Loading...",
20→  [Variant.Success]: "Success!",
21→  [Variant.Warning]: "Error!",
22→};
23→
24→const SECOND = 1000;
25→const TOAST_TIMEOUT = 30 * SECOND;
26→
27→export {
28→  mapLeafyGreenVariantToToast,
29→  mapLeafyGreenVariantToTitle,
30→  TOAST_TIMEOUT,
31→};
