 1→import { trace } from "@opentelemetry/api";
 2→import { ActionType, AnalyticsProperties } from "./types";
 3→
 4→/**
 5→ * `sendEventTrace` is a function that sends an event to our analytics provider in the form of a OTEL trace
 6→ * @param action - The action to send to our analytics provider
 7→ * @param action.name - The name of the action to send to our analytics provider
 8→ * @param properties - The properties to send with the event
 9→ */
10→export const sendEventTrace = <A extends ActionType>(
11→  { name, ...actionProps }: A,
12→  properties: AnalyticsProperties,
13→) => {
14→  const { AttributeStore } = window;
15→  if (!AttributeStore) {
16→    console.error("AttributeStore not found on window object");
17→    return;
18→  }
19→  const globalAttributes = AttributeStore.getGlobalAttributes() ?? {};
20→  const tracer = trace.getTracer("analytics");
21→
22→  tracer.startActiveSpan(name, (span) => {
23→    span.setAttributes({
24→      ...globalAttributes,
25→      ...properties,
26→      ...actionProps,
27→    });
28→    span.end();
29→  });
30→};
