import { useRef } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, waitFor } from 'storybook/test';
import Popconfirm from './index';

const meta = {
  component: Popconfirm,
  tags: ['ai-generated'],
  args: {
    children: 'Placeholder',
  },
} satisfies Meta<typeof Popconfirm>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: () => {
    const PopconfirmExample = () => {
      const triggerRef = useRef<HTMLButtonElement>(null);
      return (
        <div style={{ padding: '100px' }}>
          <button ref={triggerRef}>Delete Item</button>
          <Popconfirm
            open={true}
            setOpen={() => {}}
            refEl={triggerRef}
          >
            Are you sure you want to delete this item?
          </Popconfirm>
        </div>
      );
    };
    return <PopconfirmExample />;
  },
  play: async ({ canvasElement }) => {
    const doc = canvasElement.ownerDocument;
    await waitFor(() => {
      expect(doc.body.querySelector('[role="tooltip"]')).not.toBeNull();
    });
    await waitFor(() => {
      const cancelButton = Array.from(doc.querySelectorAll('button')).find(
        (btn) => btn.textContent === 'Cancel',
      );
      expect(cancelButton).toBeTruthy();
    });
  },
};

export const WithCustomConfirmText: Story = {
  render: () => {
    const PopconfirmExample = () => {
      const triggerRef = useRef<HTMLButtonElement>(null);
      return (
        <div style={{ padding: '100px' }}>
          <button ref={triggerRef}>Remove</button>
          <Popconfirm
            open={true}
            setOpen={() => {}}
            refEl={triggerRef}
            confirmText="Confirm"
          >
            Are you sure?
          </Popconfirm>
        </div>
      );
    };
    return <PopconfirmExample />;
  },
  play: async ({ canvasElement }) => {
    const doc = canvasElement.ownerDocument;
    await waitFor(() => {
      const confirmButton = Array.from(doc.querySelectorAll('button')).find(
        (btn) => btn.textContent === 'Confirm',
      );
      expect(confirmButton).toBeTruthy();
    });
  },
};

export const ConfirmDisabled: Story = {
  render: () => {
    const PopconfirmExample = () => {
      const triggerRef = useRef<HTMLButtonElement>(null);
      return (
        <div style={{ padding: '100px' }}>
          <button ref={triggerRef}>Action</button>
          <Popconfirm
            open={true}
            setOpen={() => {}}
            refEl={triggerRef}
            confirmDisabled
          >
            This action is not available right now.
          </Popconfirm>
        </div>
      );
    };
    return <PopconfirmExample />;
  },
  play: async ({ canvasElement }) => {
    const doc = canvasElement.ownerDocument;
    await waitFor(() => {
      const yesButton = Array.from(doc.querySelectorAll('button')).find(
        (btn) => btn.textContent === 'Yes',
      );
      expect(yesButton).toBeTruthy();
      expect(yesButton!.getAttribute('aria-disabled')).toBe('true');
    });
  },
};

import { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect } from 'storybook/test';
import { TreeSelect, ALL_VALUE, TreeDataEntry } from './TreeSelect';

const sampleData: TreeDataEntry[] = [
  {
    title: 'All',
    value: ALL_VALUE,
    key: 'all',
  },
  {
    title: 'Fruits',
    value: 'fruits',
    key: 'fruits',
    children: [
      { title: 'Apple', value: 'apple', key: 'apple' },
      { title: 'Banana', value: 'banana', key: 'banana' },
    ],
  },
  {
    title: 'Vegetables',
    value: 'vegetables',
    key: 'vegetables',
    children: [
      { title: 'Carrot', value: 'carrot', key: 'carrot' },
      { title: 'Broccoli', value: 'broccoli', key: 'broccoli' },
    ],
  },
];

const meta = {
  component: TreeSelect,
  tags: ['ai-generated'],
  args: {
    tData: sampleData,
    state: [],
    onChange: () => {},
  },
} satisfies Meta<typeof TreeSelect>;

export default meta;
type Story = StoryObj<typeof meta>;

export const NoneSelected: Story = {
  render: () => {
    const Wrapper = () => {
      const [state, setState] = useState<string[]>([]);
      return <TreeSelect tData={sampleData} state={state} onChange={setState} />;
    };
    return <Wrapper />;
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('All')).toBeVisible();
    await expect(canvas.getByText('Fruits')).toBeVisible();
    await expect(canvas.getByText('Vegetables')).toBeVisible();
  },
};

export const AllSelected: Story = {
  render: () => {
    const Wrapper = () => {
      const allValues = [ALL_VALUE, 'fruits', 'apple', 'banana', 'vegetables', 'carrot', 'broccoli'];
      const [state, setState] = useState<string[]>(allValues);
      return <TreeSelect tData={sampleData} state={state} onChange={setState} />;
    };
    return <Wrapper />;
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('All')).toBeVisible();
    await expect(canvas.getByText('Apple')).toBeVisible();
    await expect(canvas.getByText('Banana')).toBeVisible();
    await expect(canvas.getByText('Carrot')).toBeVisible();
    await expect(canvas.getByText('Broccoli')).toBeVisible();
  },
};

export const PartialSelection: Story = {
  render: () => {
    const Wrapper = () => {
      const [state, setState] = useState<string[]>(['fruits', 'apple', 'banana']);
      return <TreeSelect tData={sampleData} state={state} onChange={setState} />;
    };
    return <Wrapper />;
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('Fruits')).toBeVisible();
    await expect(canvas.getByText('Apple')).toBeVisible();
  },
};
